sys_script.script:
/* global x_hccc_hoc_ohs */
(function executeRule(current, previous /*null when async*/ ) {
    const telwrkUtils = new x_hccc_hoc_ohs.HoCOHSMTelWrkUtils();
    const res = telwrkUtils.sendToUnit4(current);

    gs.debug('OHS - Telework - Business Rule "Send info to Unit 4 after approval" result: ' + res);
})(current, previous);
